  b0 = b1;
  b1 = b2;
  b2 = 2.0 * u * b1 - b0;
  s += 0.0325114529913781 * b2;
  b0 = b1;
  b1 = b2;
  b2 = 2.0 * u * b1 - b0;
  s += -0.00959926225761849 * b2;
  b0 = b1;
  b1 = b2;
  b2 = 2.0 * u * b1 - b0;
  s += -0.003829589999638488 * b2;
  b0 = b1;
  b1 = b2;
  b2 = 2.0 * u * b1 - b0;
